@dataclass(slots=True, kw_only=True)
class SendPushNotificationRequest:
    """SendPushNotificationRequest sends a push notification. The request is
    queued and sent to the provider by Centrifugo workers.
    Centrifugo PRO only.
    """

    api_method: ClassVar[str] = "send_push_notification"
    """The server API method the request is sent to."""

    recipient: PushRecipient | None = None
    """recipient is who receives the notification. Required."""

    notification: PushNotification | None = None
    """notification is the notification to send. Required."""

    uid: str = ""
    """uid is a unique identifier of the request, can be used to cancel the
    push. UUID v4 is recommended; different requests must use different
    uids.
    """

    send_at: int = 0
    """send_at is the Unix time in seconds when to send the notification. If
    not set, the notification is sent immediately.
    """

    optimize_for_reliability: bool = False
    """optimize_for_reliability makes processing heavier, but tolerates edge
    cases, like not losing inflight pushes when the queue is briefly
    unavailable.
    """

    limit_strategy: PushLimitStrategy | None = None
    """limit_strategy sets time constraints and rate limits. Only applies
    with a filter recipient; devices are then processed one by one
    instead of in batches.
    """

    analytics_uid: str = ""
    """analytics_uid is the identifier for push notification analytics. If
    not set, uid is used.
    """

    localizations: dict[str, PushLocalization] = field(default_factory=dict)
    """localizations are optional per language/locale localizations. Setting
    them enables templating.
    """

    use_templating: bool = False
    """use_templating enables templating of the notification. Only works
    with a filter recipient.
    """

    use_meta: bool = False
    """use_meta additionally loads device meta while sending, making it
    available in templating.
    """

    def _to_wire(self) -> dict[str, Any]:
        w: dict[str, Any] = {}
        if self.recipient is not None and (v := self.recipient._to_wire()):
            w["recipient"] = v
        if self.notification is not None and (v := self.notification._to_wire()):
            w["notification"] = v
        if self.uid:
            w["uid"] = self.uid
        if self.send_at:
            w["send_at"] = self.send_at
        if self.optimize_for_reliability:
            w["optimize_for_reliability"] = self.optimize_for_reliability
        if self.limit_strategy is not None and (v := self.limit_strategy._to_wire()):
            w["limit_strategy"] = v
        if self.analytics_uid:
            w["analytics_uid"] = self.analytics_uid
        if self.localizations:
            w["localizations"] = {k: v._to_wire() for k, v in self.localizations.items()}
        if self.use_templating:
            w["use_templating"] = self.use_templating
        if self.use_meta:
            w["use_meta"] = self.use_meta
        return w

    @classmethod
    def _from_wire(cls, v: Any, where: str = "SendPushNotificationRequest") -> SendPushNotificationRequest:
        d = _w.obj(v, where)
        return cls(
            recipient=_w.message(d, "recipient", "SendPushNotificationRequest.recipient", PushRecipient._from_wire),
            notification=_w.message(
                d, "notification", "SendPushNotificationRequest.notification", PushNotification._from_wire
            ),
            uid=_w.scalar(d, "uid", "SendPushNotificationRequest.uid", _w.c_str, ""),
            send_at=_w.scalar(d, "send_at", "SendPushNotificationRequest.send_at", _w.c_int, 0),
            optimize_for_reliability=_w.scalar(
                d, "optimize_for_reliability", "SendPushNotificationRequest.optimize_for_reliability", _w.c_bool, False
            ),
            limit_strategy=_w.message(
                d, "limit_strategy", "SendPushNotificationRequest.limit_strategy", PushLimitStrategy._from_wire
            ),
            analytics_uid=_w.scalar(d, "analytics_uid", "SendPushNotificationRequest.analytics_uid", _w.c_str, ""),
            localizations=_w.dict_of(
                d, "localizations", "SendPushNotificationRequest.localizations", PushLocalization._from_wire
            ),
            use_templating=_w.scalar(
                d, "use_templating", "SendPushNotificationRequest.use_templating", _w.c_bool, False
            ),
            use_meta=_w.scalar(d, "use_meta", "SendPushNotificationRequest.use_meta", _w.c_bool, False),
        )


